class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        if (n == 0 || k == 0) return new int[0];

        int[] res = new int[n - k + 1];   // 窗口个数是 n-k+1，别开错
        for (int i = 0; i <= n - k; i++) {
            int mx = nums[i];
            for (int j = i + 1; j < i + k; j++) {
                if (nums[j] > mx) mx = nums[j];
            }
            res[i] = mx;
        }
        return res;
    }
}

import java.util.*;

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        if (n == 0 || k == 0) return new int[0];

        int[] res = new int[n - k + 1];
        // 大顶堆，按值降序；值相同时按下标降序（保持稳定）
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) ->
                a[0] != b[0] ? b[0] - a[0] : b[1] - a[1]);

        for (int i = 0; i < n; i++) {
            pq.offer(new int[]{nums[i], i});
            if (i >= k - 1) {
                // 懒删除：堆顶下标滑出窗口就弹掉
                while (pq.peek()[1] <= i - k) pq.poll();
                res[i - k + 1] = pq.peek()[0];
            }
        }
        return res;
    }
}

import java.util.*;

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        if (n == 0 || k == 0) return new int[0];

        int[] res = new int[n - k + 1];
        Deque<Integer> dq = new ArrayDeque<>();   // 存下标，值递减

        for (int i = 0; i < n; i++) {
            // 1. 队尾所有「值 <= 当前值」的下标都没用了，弹掉
            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) {
                dq.pollLast();
            }
            // 2. 当前下标入队尾
            dq.offerLast(i);
            // 3. 队首过期就弹出（滑出窗口左边）
            if (dq.peekFirst() <= i - k) {
                dq.pollFirst();
            }
            // 4. 窗口满了就记录队首对应的值
            if (i >= k - 1) {
                res[i - k + 1] = nums[dq.peekFirst()];
            }
        }
        return res;
    }
}
